class MatrixAccess {
    int grid[100];
public:
    // Overload the function call operator
    // Allows accessing elements using object(row, col) syntax
    int& operator()(size_t row, size_t col) {
        return grid[row * 10 + col];
    }

    // const version for read access
    int operator()(size_t row, size_t col) const {
        return grid[row * 10 + col];
    }
};

MatrixAccess m;
m(1, 5) = 99;
int val = m(1, 5); // 99
